//parse data from page and store stuff\n        let p = this.$store.dispatch('initializePublicPmode');\n        p.then(function () {\n            // me.$router.push('meeting-home');\n\n            // if()\n\n            window.console.log('voteomatic', 'isReady', 159, me.isReady);\n        });\n\n        // me.$router.push('meeting-home');\n\n    }\n\n\n}\n<\/script>\n\n<style scoped>\n.refresh-area {\n    margin-top: 2em;\n}\n</style>\n"],sourceRoot:""}]);const s=a},524(e,t,n){"use strict";n.d(t,{A:()=>s});var i=n(4991),o=n.n(i),r=n(6314),a=n.n(r)()(o());a.push([e.id,".chair-indicator[data-v-593b33e8]{margin-top:3em}","",{version:3,sources:["webpack://./resources/js/components/text-display/chair-indicator.vue"],names:[],mappings:"AAgDA,kCACI,cACJ",sourcesContent:['<template>\n\n    <div class="chair-indicator"\n         v-if="isChair"\n    >\n        <div class="row">\n            <div class="col">\n                <div class="alert alert-primary text-center fs-4" role="alert">\n                    Chair\n                </div>\n            </div>\n        </div>\n\n        <div class="row">\n            <div class="col text-end">\n                <force-page-reload-button></force-page-reload-button>\n            </div>\n        </div>\n\n    </div>\n\n</template>\n\n<script>\nimport ForcePageReloadButton from "../pmode/controls/force-page-reload-button.vue";\n\nexport default {\n    name: "chair-indicator",\n    components: {ForcePageReloadButton},\n\n    props: [],\n\n    mixins: [],\n\n    data: function () {\n        return {}\n    },\n\n    computed: {\n        isChair: function () {\n            return this.$store.getters.getIsAdmin;\n        }\n    }\n\n}\n<\/script>\n\n<style scoped>\n.chair-indicator {\n    margin-top: 3em;\n}\n</style>\n'],sourceRoot:""}]);const s=a},5169(e,t,n){"use strict";n.d(t,{A:()=>s});var i=n(4991),o=n.n(i),r=n(6314),a=n.n(r)()(o());a.push([e.id,".nayText[data-v-28144893]{font-weight:700}","",{version:3,sources:["webpack://./resour